# ==========================================================
# Public API
# ==========================================================

def get_chapters() -> list[dict[str, Any]]:
    """Return all International Trade chapters."""
    return [
        dict(chapter)
        for chapter in INTERNATIONAL_TRADE_CURRICULUM
    ]


def get_chapter(
    chapter_id: str,
) -> dict[str, Any] | None:
    """Return one chapter by ID."""

    normalized = str(
        chapter_id
    ).strip()

    if not normalized:
        return None

    for chapter in INTERNATIONAL_TRADE_CURRICULUM:
        if chapter.get("id") == normalized:
            return dict(chapter)

    return None


def get_lessons(
    chapter_id: str,
) -> list[dict[str, Any]]:
    """Return all lessons for a chapter."""

    normalized = str(
        chapter_id
    ).strip()

    if not normalized:
        return []

    return [
        dict(lesson)
        for lesson in INTERNATIONAL_TRADE_LESSONS.get(
            normalized,
            [],
        )
    ]


def get_lesson(
    chapter_id: str,
    lesson_id: str,
) -> dict[str, Any] | None:
    """Return one lesson."""

    chapter = str(
        chapter_id
    ).strip()

    lesson_key = str(
        lesson_id
    ).strip()

    if not chapter or not lesson_key:
        return None

    for lesson in INTERNATIONAL_TRADE_LESSONS.get(
        chapter,
        [],
    ):
        if lesson.get("id") == lesson_key:
            return dict(lesson)

    return None


def get_quiz_questions(
    chapter_id: str,
    lesson_id: str,
) -> list[dict[str, Any]]:
    """Return quiz questions for a lesson."""

    chapter = str(
        chapter_id
    ).strip()

    lesson_key = str(
        lesson_id
    ).strip()

    if not chapter or not lesson_key:
        return []

    return [
        dict(question)
        for question in INTERNATIONAL_TRADE_QUIZ_QUESTIONS.get(
            (
                chapter,
                lesson_key,
            ),
            [],
        )
    ]


# ==========================================================
# Compatibility Helpers
# ==========================================================

def get_trade_chapters() -> list[dict[str, Any]]:
    """Compatibility wrapper."""
    return get_chapters()


def get_trade_chapter(
    chapter_id: str,
) -> dict[str, Any] | None:
    """Compatibility wrapper."""
    return get_chapter(
        chapter_id
    )


def get_trade_lessons(
    chapter_id: str,
) -> list[dict[str, Any]]:
    """Compatibility wrapper."""
    return get_lessons(
        chapter_id
    )


def get_trade_lesson(
    chapter_id: str,
    lesson_id: str,
) -> dict[str, Any] | None:
    """Compatibility wrapper."""
    return get_lesson(
        chapter_id,
        lesson_id,
    )


def get_trade_quiz(
    chapter_id: str,
    lesson_id: str,
) -> list[dict[str, Any]]:
    """Compatibility wrapper."""
    return get_quiz_questions(
        chapter_id,
        lesson_id,
    )


def get_trade_quiz_questions(
    chapter_id: str,
    lesson_id: str,
) -> list[dict[str, Any]]:
    """Compatibility wrapper."""
    return get_quiz_questions(
        chapter_id,
        lesson_id,
    )


def get_quiz_questions_for_lesson(
    chapter_id: str,
    lesson_id: str,
) -> list[dict[str, Any]]:
    """Compatibility wrapper."""
    return get_quiz_questions(
        chapter_id,
        lesson_id,
    )


def get_chapter_by_id(
    chapter_id: str,
) -> dict[str, Any] | None:
    """Compatibility wrapper."""
    return get_chapter(
        chapter_id
    )


def get_lesson_by_id(
    chapter_id: str,
    lesson_id: str,
) -> dict[str, Any] | None:
    """Compatibility wrapper."""
    return get_lesson(
        chapter_id,
        lesson_id,
    )


# ==========================================================
# Module Statistics
# ==========================================================

def get_curriculum_statistics() -> dict[str, int]:
    """Return curriculum statistics."""

    chapters = len(
        INTERNATIONAL_TRADE_CURRICULUM
    )

    lessons = sum(
        len(lessons)
        for lessons in INTERNATIONAL_TRADE_LESSONS.values()
    )

    questions = sum(
        len(questions)
        for questions in INTERNATIONAL_TRADE_QUIZ_QUESTIONS.values()
    )

    return {
        "modules": 1,
        "chapters": chapters,
        "lessons": lessons,
        "questions": questions,
        "quiz_questions": questions,
    }


def get_curriculum_stats() -> dict[str, int]:
    """Compatibility alias."""
    return get_curriculum_statistics()


def get_module_statistics() -> dict[str, Any]:
    """Return module statistics."""

    return {
        "module_id": MODULE_ID,
        "title": MODULE_TITLE,
        **get_curriculum_statistics(),
    }


# ==========================================================
# Module Information
# ==========================================================

def get_module_info() -> dict[str, Any]:
    """Return complete module information."""

    statistics = (
        get_curriculum_statistics()
    )

    return {
        "id": MODULE_ID,
        "module_id": MODULE_ID,
        "title": MODULE_TITLE,
        "description": MODULE_DESCRIPTION,
        "version": MODULE_VERSION,
        "level": MODULE_LEVEL,
        "language": MODULE_LANGUAGE,
        **statistics,
    }


# ==========================================================
# All Lessons
# ==========================================================

def get_all_lessons() -> list[dict[str, Any]]:
    """Return all lessons."""

    result: list[dict[str, Any]] = []

    for chapter in INTERNATIONAL_TRADE_CURRICULUM:

        chapter_id = chapter.get(
            "id"
        )

        if not chapter_id:
            continue

        for lesson in get_lessons(
            str(chapter_id)
        ):
            item = dict(
                lesson
            )

            item.setdefault(
                "chapter_id",
                chapter_id,
            )

            result.append(
                item
            )

    return result


# ==========================================================
# All Questions
# ==========================================================

def get_all_questions() -> list[dict[str, Any]]:
    """Return all quiz questions."""

    result: list[dict[str, Any]] = []

    for (
        key,
        questions,
    ) in INTERNATIONAL_TRADE_QUIZ_QUESTIONS.items():

        chapter_id, lesson_id = key

        for question in questions:

            item = dict(
                question
            )

            item.setdefault(
                "chapter_id",
                chapter_id,
            )

            item.setdefault(
                "lesson_id",
                lesson_id,
            )

            result.append(
                item
            )

    return result


# ==========================================================
# Search
# ==========================================================

def search_lessons(
    keyword: str,
) -> list[dict[str, Any]]:
    """Search lessons by keyword."""

    normalized = str(
        keyword
    ).strip().casefold()

    if not normalized:
        return []

    results: list[
        dict[str, Any]
    ] = []

    for chapter in INTERNATIONAL_TRADE_CURRICULUM:

        chapter_id = str(
            chapter.get(
                "id",
                "",
            )
        )

        for lesson in get_lessons(
            chapter_id
        ):

            title = str(
                lesson.get(
                    "title",
                    "",
                )
            )

            content = str(
                lesson.get(
                    "content",
                    "",
                )
            )

            keywords = " ".join(
                str(item)
                for item in lesson.get(
                    "keywords",
                    [],
                )
            )

            searchable = (
                f"{title}\n"
                f"{content}\n"
                f"{keywords}"
            ).casefold()

            if normalized in searchable:

                results.append(
                    {
                        "module_id": MODULE_ID,
                        "chapter_id": chapter_id,
                        "lesson_id": lesson.get(
                            "id"
                        ),
                        "title": title,
                    }
                )

    return results


# ==========================================================
# Data Health Check
# ==========================================================

def data_health_check() -> bool:
    """Validate complete International Trade module data integrity."""

    try:
        if not MODULE_ID or not MODULE_TITLE:
            return False

        if not isinstance(INTERNATIONAL_TRADE_CURRICULUM, list):
            return False

        if len(INTERNATIONAL_TRADE_CURRICULUM) != 12:
            return False

        all_question_ids: set[str] = set()
        total_lessons = 0
        total_questions = 0

        chapter_ids: set[str] = set()

        for chapter in INTERNATIONAL_TRADE_CURRICULUM:
            if not isinstance(chapter, dict):
                return False

            chapter_id = str(chapter.get("id", "")).strip()
            if not chapter_id or chapter_id in chapter_ids:
                return False
            chapter_ids.add(chapter_id)

            lessons = INTERNATIONAL_TRADE_LESSONS.get(chapter_id)
            if not isinstance(lessons, list):
                return False

            lesson_ids: set[str] = set()

            for lesson in lessons:
                if not isinstance(lesson, dict):
                    return False

                lesson_id = str(lesson.get("id", "")).strip()
                if not lesson_id or lesson_id in lesson_ids:
                    return False

                lesson_ids.add(lesson_id)
                total_lessons += 1

                if not lesson.get("title") or not lesson.get("content"):
                    return False

                questions = INTERNATIONAL_TRADE_QUIZ_QUESTIONS.get(
                    (chapter_id, lesson_id),
                    [],
                )

                if not isinstance(questions, list) or len(questions) != 5:
                    return False

                for question in questions:
                    if not isinstance(question, dict):
                        return False

                    question_id = str(question.get("id", "")).strip()
                    if not question_id or question_id in all_question_ids:
                        return False
                    all_question_ids.add(question_id)

                    if not str(question.get("question", "")).strip():
                        return False

                    options = question.get("options")
                    if not isinstance(options, list) or len(options) != 4:
                        return False

                    option_ids = []
                    for option in options:
                        if not isinstance(option, dict):
                            return False
                        option_id = str(option.get("id", "")).strip()
                        option_text = str(option.get("text", "")).strip()
                        if option_id not in {"A", "B", "C", "D"} or not option_text:
                            return False
                        option_ids.append(option_id)

                    if set(option_ids) != {"A", "B", "C", "D"}:
                        return False

                    answer = str(question.get("answer", "")).strip()
                    correct_answer = str(question.get("correct_answer", "")).strip()

                    if answer not in {"A", "B", "C", "D"}:
                        return False

                    if correct_answer not in {"A", "B", "C", "D"}:
                        return False

                    if answer != correct_answer:
                        return False

                    if not str(question.get("explanation", "")).strip():
                        return False

                    total_questions += 1

        if total_lessons != 32:
            return False

        if total_questions != 160:
            return False

        return True

    except Exception:
        return False



# ==========================================================
# Detailed Validation
# ==========================================================

def validate_module() -> dict[str, Any]:
    """Return detailed curriculum and quiz validation."""

    errors: list[str] = []
    warnings: list[str] = []

    chapters = get_chapters()
    if len(chapters) != 12:
        errors.append(f"Expected 12 chapters, found {len(chapters)}.")

    total_lessons = 0
    total_questions = 0
    question_ids: set[str] = set()

    for chapter in chapters:
        chapter_id = str(chapter.get("id", "")).strip()
        lessons = get_lessons(chapter_id)
        total_lessons += len(lessons)

        for lesson in lessons:
            lesson_id = str(lesson.get("id", "")).strip()
            questions = get_quiz_questions(chapter_id, lesson_id)

            if len(questions) != 5:
                errors.append(
                    f"{chapter_id}/{lesson_id}: expected 5 questions, found {len(questions)}."
                )

            for index, question in enumerate(questions, start=1):
                qid = str(question.get("id", "")).strip()

                if not qid:
                    errors.append(f"{chapter_id}/{lesson_id}/q{index}: missing ID.")
                elif qid in question_ids:
                    errors.append(f"Duplicate question ID: {qid}")
                else:
                    question_ids.add(qid)

                options = question.get("options")
                if not isinstance(options, list) or len(options) != 4:
                    errors.append(
                        f"{chapter_id}/{lesson_id}/q{index}: expected exactly 4 options."
                    )
                else:
                    option_ids = {
                        str(item.get("id", "")).strip()
                        for item in options
                        if isinstance(item, dict)
                    }
                    if option_ids != {"A", "B", "C", "D"}:
                        errors.append(
                            f"{chapter_id}/{lesson_id}/q{index}: option IDs must be A/B/C/D."
                        )

                answer = str(question.get("answer", "")).strip()
                correct = str(question.get("correct_answer", "")).strip()

                if answer not in {"A", "B", "C", "D"}:
                    errors.append(
                        f"{chapter_id}/{lesson_id}/q{index}: invalid answer '{answer}'."
                    )

                if correct not in {"A", "B", "C", "D"}:
                    errors.append(
                        f"{chapter_id}/{lesson_id}/q{index}: invalid correct_answer '{correct}'."
                    )

                if answer != correct:
                    errors.append(
                        f"{chapter_id}/{lesson_id}/q{index}: answer and correct_answer differ."
                    )

                if not str(question.get("explanation", "")).strip():
                    errors.append(
                        f"{chapter_id}/{lesson_id}/q{index}: missing explanation."
                    )

            total_questions += len(questions)

    if total_lessons != 32:
        errors.append(f"Expected 32 lessons, found {total_lessons}.")

    if total_questions != 160:
        errors.append(f"Expected 160 questions, found {total_questions}.")

    statistics = get_curriculum_statistics()

    return {
        "valid": not errors,
        "errors": errors,
        "warnings": warnings,
        "statistics": statistics,
        "expected": {
            "chapters": 12,
            "lessons": 32,
            "questions": 160,
            "questions_per_lesson": 5,
            "options_per_question": 4,
        },
    }



